{"version":3,"file":"actions.min.js","sources":["../../../src/local/courseai/actions.js"],"sourcesContent":["// This file is part of Moodle - http://moodle.org/\n//\n// Moodle is free software: you can redistribute it and/or modify\n// it under the terms of the GNU General Public License as published by\n// the Free Software Foundation, either version 3 of the License, or\n// (at your option) any later version.\n//\n// Moodle is distributed in the hope that it will be useful,\n// but WITHOUT ANY WARRANTY; without even the implied warranty of\n// MERCHANTABILITY or FITNESS FOR A PARTICULAR PURPOSE.  See the\n// GNU General Public License for more details.\n//\n// You should have received a copy of the GNU General Public License\n// along with Moodle.  If not, see <http://www.gnu.org/licenses/>.\n\n/**\n * Course AI action handlers — orchestrator.\n *\n * Assembles the public action API from focused submodules and wires DOM events.\n *\n * @module     local_coursegen/local/courseai/actions\n * @copyright  2026 Wilber Narvaez <https://datacurso.com>\n * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later\n */\n\nimport { setCompactChatState } from './ui-planning';\nimport FormAutocomplete from 'core/form-autocomplete';\nimport { buildCompletionSummary } from './actions/summary';\nimport { showCourseReviewPanel, createCourseFromSession } from './actions/course-create';\nimport { sendFeedbackAction } from './actions/feedback';\nimport { handleGenerate } from './actions/generate';\n\n/**\n * Create courseai actions and event bindings.\n *\n * @param {Object} deps\n * @returns {Object}\n */\nexport const createCourseaiActions = (deps) => {\n    const {\n        state, elements, Notification, CourseaiRepository,\n        sendPlanningFeedback, createCourse, getCourseSettings,\n        updateGenerateButton, refreshChipsRow, refreshGuidelineChip,\n        stepsUi, planningUi, streamManager, texts, formatTemplate, emitLog,\n    } = deps;\n\n    const {\n        promptInput, btnGenerate, btnApprove, planActions,\n        pcToggleBtn, pcDetailsPanel, pcChevron,\n        planningProgressCard, completionView, completionSummary,\n        btnOpenMoodleCourse, btnCreateAnotherCourse,\n        btnWithImages, imgToggleWrap, langSelect,\n        btnWithSubsections, subToggleWrap,\n        compactPromptInput, btnCompactRegenerate,\n        initialPromptHistory, initialPromptText,\n    } = elements;\n\n    const renderInitialPromptHistory = (message) => {\n        if (initialPromptText) {\n            initialPromptText.textContent = message || '';\n        }\n        if (initialPromptHistory) {\n            initialPromptHistory.classList.toggle('hidden', !message);\n        }\n    };\n\n    /**\n     * Fire a celebratory confetti burst from the completion badge: colourful pieces\n     * shoot outward from the cone and arc down under gravity, spinning and fading.\n     * Uses the Web Animations API (no external assets). Skipped under reduced motion.\n     *\n     * @param {HTMLElement} container - The .pc-confetti layer inside the badge.\n     * @returns {void}\n     */\n    const fireConfetti = (container) => {\n        if (!container) {\n            return;\n        }\n        if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {\n            return;\n        }\n        const colors = ['#ED6E54', '#F1AA1E', '#5B4590', '#3B9EE5', '#E5528A', '#3FBF6F'];\n        const rand = (min, max) => min + Math.random() * (max - min);\n        const count = 40;\n        for (let i = 0; i < count; i++) {\n            const piece = document.createElement('i');\n            const circle = i % 3 === 0;\n            const w = circle ? rand(5, 8) : rand(4, 7);\n            const h = circle ? w : rand(8, 14);\n            piece.style.cssText = 'position:absolute;top:42%;left:50%;'\n                + 'width:' + w.toFixed(1) + 'px;height:' + h.toFixed(1) + 'px;'\n                + 'background:' + colors[i % colors.length] + ';'\n                + 'border-radius:' + (circle ? '50%' : '1px') + ';will-change:transform,opacity;';\n            container.appendChild(piece);\n            // Burst mostly upward/outward (a popper fires up), then gravity pulls it down.\n            // Long throws so the confetti reaches far across the view.\n            const angle = rand(-178, -2) * Math.PI / 180;\n            const dist = rand(150, 360);\n            const bx = Math.cos(angle) * dist;\n            const by = Math.sin(angle) * dist;\n            const fallY = by + rand(230, 520);\n            const drift = bx + rand(-40, 40);\n            const spin = (i % 2 ? 1 : -1) * rand(240, 620);\n            const midX = bx + (drift - bx) * 0.5;\n            const midY = by + (fallY - by) * 0.5;\n            const peak = 'translate(calc(-50% + ' + bx.toFixed(1) + 'px), calc(-50% + '\n                + by.toFixed(1) + 'px)) scale(1) rotate(' + (spin * 0.35).toFixed(0) + 'deg)';\n            const mid = 'translate(calc(-50% + ' + midX.toFixed(1) + 'px), calc(-50% + '\n                + midY.toFixed(1) + 'px)) scale(1) rotate(' + (spin * 0.7).toFixed(0) + 'deg)';\n            const end = 'translate(calc(-50% + ' + drift.toFixed(1) + 'px), calc(-50% + '\n                + fallY.toFixed(1) + 'px)) scale(.9) rotate(' + spin.toFixed(0) + 'deg)';\n            // Quick burst out (to ~0.28), then a SLOW gravity fall + late fade so the\n            // tail lingers — the last third of the (longer) duration is the settle.\n            const anim = piece.animate([\n                {transform: 'translate(-50%,-50%) scale(.4) rotate(0deg)', opacity: 0, offset: 0},\n                {opacity: 1, offset: 0.1},\n                {transform: peak, opacity: 1, offset: 0.28},\n                {transform: mid, opacity: 1, offset: 0.68},\n                {transform: end, opacity: 0, offset: 1}\n            ], {duration: rand(1700, 2700), easing: 'cubic-bezier(.1,.55,.25,1)', fill: 'forwards'});\n            // Clean each piece up when it finishes (both bursts leave no DOM behind).\n            anim.onfinish = () => piece.remove();\n        }\n    };\n\n    const showCompletionView = (result) => {\n        state.createdCourseResult = result || null;\n        state.createdCourseUrl = result?.courseurl || '';\n        state.currentStage = 'completed';\n        // The course is created and can no longer be edited from this wizard, so the\n        // composer must be gone on the success view. Hide it explicitly here (not only\n        // via the body-class CSS) so a stale/aggregated stylesheet can't leave it\n        // visible, and keep the declarative class in sync.\n        state.planApproved = true;\n        document.body.classList.add('cg-plan-approved');\n        if (elements.compactChatCard) {\n            elements.compactChatCard.style.display = 'none';\n        }\n        if (completionSummary) {\n            completionSummary.textContent = buildCompletionSummary(state, texts, formatTemplate);\n        }\n        if (planningProgressCard) { planningProgressCard.style.display = 'none'; }\n        if (elements.planReviewCard) { elements.planReviewCard.style.display = 'none'; }\n        if (planActions) { planActions.style.display = 'none'; }\n        // Generation is over: drop the live progress view (the plan cards) so only the\n        // success panel shows, and clear the generation styling.\n        document.body.classList.remove('cg-generating');\n        if (elements.planDetailedView) { elements.planDetailedView.style.display = 'none'; }\n        if (completionView) { completionView.style.display = 'flex'; }\n        if (btnOpenMoodleCourse) { btnOpenMoodleCourse.disabled = !state.createdCourseUrl; }\n        stepsUi.setStepState('planning', 'done');\n        stepsUi.setStepState('generating', 'done');\n        stepsUi.updateFlowNav();\n        // Drop any lingering \"working\" indicator (e.g. the one shown when the user hit\n        // Accept). Generation is over, so it must not sit in the bottom slot beside the\n        // success view.\n        const workingEntry = document.getElementById('cgFeedbackThinking');\n        if (workingEntry) { workingEntry.remove(); }\n        // Pin the left thread to the bottom so the final \"Your course is ready\" turn is\n        // comfortably visible. Without this the newest turns sit below the fold and the\n        // user has to scroll down to see the completion message. Deferred to the next\n        // frame so it runs after this view's layout changes settle.\n        const chatScroll = document.getElementById('courseaiChatScroll');\n        if (chatScroll) {\n            window.requestAnimationFrame(() => {\n                chatScroll.scrollTop = chatScroll.scrollHeight;\n            });\n        }\n        // Celebratory confetti — a DOUBLE pop. Both bursts run the SAME animation; the\n        // second fires ~1.5s later: late enough to read as a distinct second pop, but\n        // while the first is still falling so there is NO empty gap between them (2s\n        // left a dead pause; 1.2s felt almost simultaneous).\n        const confettiLayer = document.getElementById('pcConfetti');\n        fireConfetti(confettiLayer);\n        window.setTimeout(() => fireConfetti(confettiLayer), 1500);\n    };\n\n    const resetForAnotherCourse = () => {\n        state.sessionid = 0;\n        state.threadid = '';\n        state.streamingurl = '';\n        state.selectedGuidelineId = null;\n        state.syllabusFile = null;\n        state.syllabusFilename = null;\n        state.draftitemid = null;\n        state.withImages = false;\n        state.withSubsections = false;\n        state.lang = state.defaultLang;\n        state.completionStats = null;\n        state.createdCourseUrl = '';\n        state.createdCourseResult = null;\n        state.initialPrompt = '';\n        if (promptInput) { promptInput.value = ''; }\n        if (langSelect) { langSelect.value = state.lang; }\n        if (btnWithImages) { btnWithImages.checked = false; }\n        if (imgToggleWrap) { imgToggleWrap.classList.remove('on'); }\n        if (btnWithSubsections) { btnWithSubsections.checked = false; }\n        if (subToggleWrap) { subToggleWrap.classList.remove('on'); }\n        const chipSyllabus = document.getElementById('chipSyllabus');\n        if (chipSyllabus) { chipSyllabus.classList.add('hidden'); }\n        const chipSyllabusName = document.getElementById('chipSyllabusName');\n        if (chipSyllabusName) { chipSyllabusName.textContent = ''; }\n        refreshGuidelineChip();\n        refreshChipsRow();\n        renderInitialPromptHistory('');\n        stepsUi.backToContext();\n        updateGenerateButton();\n    };\n\n    /** Shared generate context built once and reused in multiple event listeners. */\n    const genCtx = () => ({\n        state, elements, texts,\n        CourseaiRepository, stepsUi, planningUi, streamManager,\n        Notification, renderInitialPromptHistory, emitLog,\n    });\n\n    /** Shared feedback context. */\n    const fbCtx = () => ({\n        state, elements, texts, Notification,\n        setCompactChatState, deps,\n        sendPlanningFeedback, streamManager,\n        stepsUi, planningUi, emitLog,\n    });\n\n    const bindEvents = () => {\n        if (promptInput) {\n            promptInput.addEventListener('input', updateGenerateButton);\n            promptInput.addEventListener('keydown', (e) => {\n                if (e.key === 'Enter' && !e.shiftKey) {\n                    e.preventDefault();\n                    handleGenerate(genCtx());\n                }\n            });\n        }\n        if (btnGenerate) {\n            btnGenerate.addEventListener('click', () => handleGenerate(genCtx()));\n        }\n        if (pcToggleBtn) {\n            pcToggleBtn.addEventListener('click', () => {\n                state.planDetailsOpen = !state.planDetailsOpen;\n                if (pcDetailsPanel) {\n                    pcDetailsPanel.style.display = state.planDetailsOpen ? 'block' : 'none';\n                }\n                pcToggleBtn.setAttribute('aria-expanded', state.planDetailsOpen ? 'true' : 'false');\n                if (pcChevron) {\n                    pcChevron.style.transform = state.planDetailsOpen ? 'rotate(90deg)' : 'rotate(0deg)';\n                }\n            });\n        }\n        if (btnApprove) {\n            btnApprove.addEventListener('click', () => sendFeedbackAction('accept', fbCtx()));\n        }\n        if (btnCompactRegenerate) {\n            btnCompactRegenerate.addEventListener('click', () => {\n                if (state.isStreaming) { return; }\n                const instruction = compactPromptInput ? compactPromptInput.value.trim() : '';\n                if (instruction.length < 10) {\n                    if (compactPromptInput) { compactPromptInput.focus(); }\n                    return;\n                }\n                sendFeedbackAction('adjust', fbCtx());\n            });\n        }\n        if (compactPromptInput && promptInput) {\n            compactPromptInput.addEventListener('input', () => {\n                promptInput.value = compactPromptInput.value;\n            });\n        }\n        const btnWizardCancel = document.getElementById('btnWizardCancel');\n        if (btnWizardCancel) {\n            btnWizardCancel.addEventListener('click', () => stepsUi.backToContext());\n        }\n        if (btnOpenMoodleCourse) {\n            btnOpenMoodleCourse.addEventListener('click', () => {\n                if (!state.createdCourseUrl) { return; }\n                window.open(state.createdCourseUrl, '_blank', 'noopener,noreferrer');\n            });\n        }\n        if (btnCreateAnotherCourse) {\n            btnCreateAnotherCourse.addEventListener('click', () => {\n                window.location.href = 'aicoursecreation.php';\n            });\n        }\n        window.clearSyllabus = () => {\n            state.syllabusFile = null;\n            state.syllabusFilename = null;\n            state.draftitemid = null;\n            const chipSyllabus = document.getElementById('chipSyllabus');\n            if (chipSyllabus) { chipSyllabus.classList.add('hidden'); }\n            refreshChipsRow();\n            const compactChipSyllabus = document.getElementById('compactChipSyllabus');\n            if (compactChipSyllabus) { compactChipSyllabus.classList.add('hidden'); }\n            const compactChipsRow = document.getElementById('compactChipsRow');\n            const compactChipGuideline = document.getElementById('compactChipGuideline');\n            if (compactChipsRow) {\n                const hasGuideline = compactChipGuideline && !compactChipGuideline.classList.contains('hidden');\n                compactChipsRow.style.display = hasGuideline ? 'flex' : 'none';\n            }\n        };\n        window.clearGuideline = () => {\n            state.selectedGuidelineId = null;\n            refreshGuidelineChip();\n        };\n    };\n\n    return {\n        showCompletionView,\n        showCourseReviewPanel: () => showCourseReviewPanel(\n            state, elements, texts, getCourseSettings, FormAutocomplete\n        ),\n        createCourseFromSession: (overrides = null) => createCourseFromSession(\n            state, elements, texts, stepsUi, Notification, createCourse, showCompletionView, overrides\n        ),\n        handleGenerate: () => handleGenerate(genCtx()),\n        sendFeedbackAction: (action) => sendFeedbackAction(action, fbCtx()),\n        resetForAnotherCourse,\n        bindEvents,\n    };\n};\n"],"names":["deps","state","elements","Notification","CourseaiRepository","sendPlanningFeedback","createCourse","getCourseSettings","updateGenerateButton","refreshChipsRow","refreshGuidelineChip","stepsUi","planningUi","streamManager","texts","formatTemplate","emitLog","promptInput","btnGenerate","btnApprove","planActions","pcToggleBtn","pcDetailsPanel","pcChevron","planningProgressCard","completionView","completionSummary","btnOpenMoodleCourse","btnCreateAnotherCourse","btnWithImages","imgToggleWrap","langSelect","btnWithSubsections","subToggleWrap","compactPromptInput","btnCompactRegenerate","initialPromptHistory","initialPromptText","renderInitialPromptHistory","message","textContent","classList","toggle","fireConfetti","container","window","matchMedia","matches","colors","rand","min","max","Math","random","i","piece","document","createElement","circle","w","h","style","cssText","toFixed","length","appendChild","angle","PI","dist","bx","cos","by","sin","fallY","drift","spin","midX","midY","peak","mid","end","animate","transform","opacity","offset","duration","easing","fill","onfinish","remove","showCompletionView","result","createdCourseResult","createdCourseUrl","courseurl","currentStage","planApproved","body","add","compactChatCard","display","planReviewCard","planDetailedView","disabled","setStepState","updateFlowNav","workingEntry","getElementById","chatScroll","requestAnimationFrame","scrollTop","scrollHeight","confettiLayer","setTimeout","genCtx","fbCtx","setCompactChatState","showCourseReviewPanel","FormAutocomplete","createCourseFromSession","overrides","handleGenerate","sendFeedbackAction","action","resetForAnotherCourse","sessionid","threadid","streamingurl","selectedGuidelineId","syllabusFile","syllabusFilename","draftitemid","withImages","withSubsections","lang","defaultLang","completionStats","initialPrompt","value","checked","chipSyllabus","chipSyllabusName","backToContext","bindEvents","addEventListener","e","key","shiftKey","preventDefault","planDetailsOpen","setAttribute","isStreaming","trim","focus","btnWizardCancel","open","location","href","clearSyllabus","compactChipSyllabus","compactChipsRow","compactChipGuideline","hasGuideline","contains","clearGuideline"],"mappings":";;;;;;;;;8MAsCsCA,aAC5BC,MACFA,MADEC,SACKA,SADLC,aACeA,aADfC,mBAC6BA,mBAD7BC,qBAEFA,qBAFEC,aAEoBA,aAFpBC,kBAEkCA,kBAFlCC,qBAGFA,qBAHEC,gBAGoBA,gBAHpBC,qBAGqCA,qBAHrCC,QAIFA,QAJEC,WAIOA,WAJPC,cAImBA,cAJnBC,MAIkCA,MAJlCC,eAIyCA,eAJzCC,QAIyDA,SAC3DhB,MAEEiB,YACFA,YADEC,YACWA,YADXC,WACwBA,WADxBC,YACoCA,YADpCC,YAEFA,YAFEC,eAEWA,eAFXC,UAE2BA,UAF3BC,qBAGFA,qBAHEC,eAGoBA,eAHpBC,kBAGoCA,kBAHpCC,oBAIFA,oBAJEC,uBAImBA,uBAJnBC,cAKFA,cALEC,cAKaA,cALbC,WAK4BA,WAL5BC,mBAMFA,mBANEC,cAMkBA,cANlBC,mBAOFA,mBAPEC,qBAOkBA,qBAPlBC,qBAQFA,qBAREC,kBAQoBA,mBACtBnC,SAEEoC,2BAA8BC,UAC5BF,oBACAA,kBAAkBG,YAAcD,SAAW,IAE3CH,sBACAA,qBAAqBK,UAAUC,OAAO,UAAWH,UAYnDI,aAAgBC,gBACbA,oBAGDC,OAAOC,YAAcD,OAAOC,WAAW,oCAAoCC,qBAGzEC,OAAS,CAAC,UAAW,UAAW,UAAW,UAAW,UAAW,WACjEC,KAAO,CAACC,IAAKC,MAAQD,IAAME,KAAKC,UAAYF,IAAMD,SAEnD,IAAII,EAAI,EAAGA,EADF,GACaA,IAAK,OACtBC,MAAQC,SAASC,cAAc,KAC/BC,OAASJ,EAAI,GAAM,EACnBK,EAAID,OAAST,KAAK,EAAG,GAAKA,KAAK,EAAG,GAClCW,EAAIF,OAASC,EAAIV,KAAK,EAAG,IAC/BM,MAAMM,MAAMC,QAAU,4CACLH,EAAEI,QAAQ,GAAK,aAAeH,EAAEG,QAAQ,GADnC,iBAEAf,OAAOM,EAAIN,OAAOgB,QAFlB,mBAGIN,OAAS,MAAQ,OAAS,kCACpDd,UAAUqB,YAAYV,aAGhBW,MAAQjB,MAAM,KAAM,GAAKG,KAAKe,GAAK,IACnCC,KAAOnB,KAAK,IAAK,KACjBoB,GAAKjB,KAAKkB,IAAIJ,OAASE,KACvBG,GAAKnB,KAAKoB,IAAIN,OAASE,KACvBK,MAAQF,GAAKtB,KAAK,IAAK,KACvByB,MAAQL,GAAKpB,MAAM,GAAI,IACvB0B,MAAQrB,EAAI,EAAI,GAAK,GAAKL,KAAK,IAAK,KACpC2B,KAAOP,GAAoB,IAAdK,MAAQL,IACrBQ,KAAON,GAAoB,IAAdE,MAAQF,IACrBO,KAAO,yBAA2BT,GAAGN,QAAQ,GAAK,oBAClDQ,GAAGR,QAAQ,GAAK,yBAAkC,IAAPY,MAAaZ,QAAQ,GAAK,OACrEgB,IAAM,yBAA2BH,KAAKb,QAAQ,GAAK,oBACnDc,KAAKd,QAAQ,GAAK,yBAAkC,GAAPY,MAAYZ,QAAQ,GAAK,OACtEiB,IAAM,yBAA2BN,MAAMX,QAAQ,GAAK,oBACpDU,MAAMV,QAAQ,GAAK,yBAA2BY,KAAKZ,QAAQ,GAAK,OAGzDR,MAAM0B,QAAQ,CACvB,CAACC,UAAW,8CAA+CC,QAAS,EAAGC,OAAQ,GAC/E,CAACD,QAAS,EAAGC,OAAQ,IACrB,CAACF,UAAWJ,KAAMK,QAAS,EAAGC,OAAQ,KACtC,CAACF,UAAWH,IAAKI,QAAS,EAAGC,OAAQ,KACrC,CAACF,UAAWF,IAAKG,QAAS,EAAGC,OAAQ,IACtC,CAACC,SAAUpC,KAAK,KAAM,MAAOqC,OAAQ,6BAA8BC,KAAM,aAEvEC,SAAW,IAAMjC,MAAMkC,WAI9BC,mBAAsBC,SACxB1F,MAAM2F,oBAAsBD,QAAU,KACtC1F,MAAM4F,kBAAmBF,MAAAA,cAAAA,OAAQG,YAAa,GAC9C7F,MAAM8F,aAAe,YAKrB9F,MAAM+F,cAAe,EACrBxC,SAASyC,KAAKxD,UAAUyD,IAAI,oBACxBhG,SAASiG,kBACTjG,SAASiG,gBAAgBtC,MAAMuC,QAAU,QAEzC1E,oBACAA,kBAAkBc,aAAc,mCAAuBvC,MAAOa,MAAOC,iBAErES,uBAAwBA,qBAAqBqC,MAAMuC,QAAU,QAC7DlG,SAASmG,iBAAkBnG,SAASmG,eAAexC,MAAMuC,QAAU,QACnEhF,cAAeA,YAAYyC,MAAMuC,QAAU,QAG/C5C,SAASyC,KAAKxD,UAAUgD,OAAO,iBAC3BvF,SAASoG,mBAAoBpG,SAASoG,iBAAiBzC,MAAMuC,QAAU,QACvE3E,iBAAkBA,eAAeoC,MAAMuC,QAAU,QACjDzE,sBAAuBA,oBAAoB4E,UAAYtG,MAAM4F,kBACjElF,QAAQ6F,aAAa,WAAY,QACjC7F,QAAQ6F,aAAa,aAAc,QACnC7F,QAAQ8F,sBAIFC,aAAelD,SAASmD,eAAe,sBACzCD,cAAgBA,aAAajB,eAK3BmB,WAAapD,SAASmD,eAAe,sBACvCC,YACA/D,OAAOgE,uBAAsB,KACzBD,WAAWE,UAAYF,WAAWG,sBAOpCC,cAAgBxD,SAASmD,eAAe,cAC9ChE,aAAaqE,eACbnE,OAAOoE,YAAW,IAAMtE,aAAaqE,gBAAgB,OAoCnDE,OAAS,MACXjH,MAAAA,MAAOC,SAAAA,SAAUY,MAAAA,MACjBV,mBAAAA,mBAAoBO,QAAAA,QAASC,WAAAA,WAAYC,cAAAA,cACzCV,aAAAA,aAAcmC,2BAAAA,2BAA4BtB,QAAAA,UAIxCmG,MAAQ,MACVlH,MAAAA,MAAOC,SAAAA,SAAUY,MAAAA,MAAOX,aAAAA,aACxBiH,oBAAAA,gCAAqBpH,KAAAA,KACrBK,qBAAAA,qBAAsBQ,cAAAA,cACtBF,QAAAA,QAASC,WAAAA,WAAYI,QAAAA,gBAoFlB,CACH0E,mBAAAA,mBACA2B,sBAAuB,KAAM,uCACzBpH,MAAOC,SAAUY,MAAOP,kBAAmB+G,2BAE/CC,wBAAyB,eAACC,iEAAY,YAAS,yCAC3CvH,MAAOC,SAAUY,MAAOH,QAASR,aAAcG,aAAcoF,mBAAoB8B,YAErFC,eAAgB,KAAM,4BAAeP,UACrCQ,mBAAqBC,SAAW,gCAAmBA,OAAQR,SAC3DS,sBA1I0B,KAC1B3H,MAAM4H,UAAY,EAClB5H,MAAM6H,SAAW,GACjB7H,MAAM8H,aAAe,GACrB9H,MAAM+H,oBAAsB,KAC5B/H,MAAMgI,aAAe,KACrBhI,MAAMiI,iBAAmB,KACzBjI,MAAMkI,YAAc,KACpBlI,MAAMmI,YAAa,EACnBnI,MAAMoI,iBAAkB,EACxBpI,MAAMqI,KAAOrI,MAAMsI,YACnBtI,MAAMuI,gBAAkB,KACxBvI,MAAM4F,iBAAmB,GACzB5F,MAAM2F,oBAAsB,KAC5B3F,MAAMwI,cAAgB,GAClBxH,cAAeA,YAAYyH,MAAQ,IACnC3G,aAAcA,WAAW2G,MAAQzI,MAAMqI,MACvCzG,gBAAiBA,cAAc8G,SAAU,GACzC7G,eAAiBA,cAAcW,UAAUgD,OAAO,MAChDzD,qBAAsBA,mBAAmB2G,SAAU,GACnD1G,eAAiBA,cAAcQ,UAAUgD,OAAO,YAC9CmD,aAAepF,SAASmD,eAAe,gBACzCiC,cAAgBA,aAAanG,UAAUyD,IAAI,gBACzC2C,iBAAmBrF,SAASmD,eAAe,oBAC7CkC,mBAAoBA,iBAAiBrG,YAAc,IACvD9B,uBACAD,kBACA6B,2BAA2B,IAC3B3B,QAAQmI,gBACRtI,wBA8GAuI,WA5Fe,KACX9H,cACAA,YAAY+H,iBAAiB,QAASxI,sBACtCS,YAAY+H,iBAAiB,WAAYC,IACvB,UAAVA,EAAEC,KAAoBD,EAAEE,WACxBF,EAAEG,8CACalC,eAIvBhG,aACAA,YAAY8H,iBAAiB,SAAS,KAAM,4BAAe9B,YAE3D7F,aACAA,YAAY2H,iBAAiB,SAAS,KAClC/I,MAAMoJ,iBAAmBpJ,MAAMoJ,gBAC3B/H,iBACAA,eAAeuC,MAAMuC,QAAUnG,MAAMoJ,gBAAkB,QAAU,QAErEhI,YAAYiI,aAAa,gBAAiBrJ,MAAMoJ,gBAAkB,OAAS,SACvE9H,YACAA,UAAUsC,MAAMqB,UAAYjF,MAAMoJ,gBAAkB,gBAAkB,mBAI9ElI,YACAA,WAAW6H,iBAAiB,SAAS,KAAM,gCAAmB,SAAU7B,WAExEhF,sBACAA,qBAAqB6G,iBAAiB,SAAS,QACvC/I,MAAMsJ,oBACUrH,mBAAqBA,mBAAmBwG,MAAMc,OAAS,IAC3DxF,OAAS,GACjB9B,oBAAsBA,mBAAmBuH,yCAG9B,SAAUtC,YAGjCjF,oBAAsBjB,aACtBiB,mBAAmB8G,iBAAiB,SAAS,KACzC/H,YAAYyH,MAAQxG,mBAAmBwG,eAGzCgB,gBAAkBlG,SAASmD,eAAe,mBAC5C+C,iBACAA,gBAAgBV,iBAAiB,SAAS,IAAMrI,QAAQmI,kBAExDnH,qBACAA,oBAAoBqH,iBAAiB,SAAS,KACrC/I,MAAM4F,kBACXhD,OAAO8G,KAAK1J,MAAM4F,iBAAkB,SAAU,0BAGlDjE,wBACAA,uBAAuBoH,iBAAiB,SAAS,KAC7CnG,OAAO+G,SAASC,KAAO,0BAG/BhH,OAAOiH,cAAgB,KACnB7J,MAAMgI,aAAe,KACrBhI,MAAMiI,iBAAmB,KACzBjI,MAAMkI,YAAc,WACdS,aAAepF,SAASmD,eAAe,gBACzCiC,cAAgBA,aAAanG,UAAUyD,IAAI,UAC/CzF,wBACMsJ,oBAAsBvG,SAASmD,eAAe,uBAChDoD,qBAAuBA,oBAAoBtH,UAAUyD,IAAI,gBACvD8D,gBAAkBxG,SAASmD,eAAe,mBAC1CsD,qBAAuBzG,SAASmD,eAAe,2BACjDqD,gBAAiB,OACXE,aAAeD,uBAAyBA,qBAAqBxH,UAAU0H,SAAS,UACtFH,gBAAgBnG,MAAMuC,QAAU8D,aAAe,OAAS,SAGhErH,OAAOuH,eAAiB,KACpBnK,MAAM+H,oBAAsB,KAC5BtH"}
